using Avalonia;
using Avalonia.Controls;
using Avalonia.Layout;
using System.Text.Json;
namespace ProjectDesk;

public sealed class McpConnectorsWindow : Window {
 private readonly McpSettingsStore _store;private readonly IMcpSecrets _secrets;private readonly ProjectSession _session;private readonly Action _refresh;
 private readonly McpProjectRevision _revision=new();private readonly McpInvocationGate _gate=new();
 private readonly ListBox _servers=new(){MinWidth=210},_tools=new(){Height=130};
 private readonly TextBox _toolSearch=new(){Watermark="Search tools"};private readonly TextBox _schema=new(){IsReadOnly=true,AcceptsReturn=true,MaxHeight=160,TextWrapping=Avalonia.Media.TextWrapping.Wrap};private readonly ProgressBar _progress=new(){IsIndeterminate=true,Height=3,IsVisible=false};
 private readonly TextBlock _status=new(){Text="Choose a server or add the demo to get started.",TextWrapping=Avalonia.Media.TextWrapping.Wrap},_description=new(){TextWrapping=Avalonia.Media.TextWrapping.Wrap};
 private readonly TextBox _arguments=new(){Text="{}",AcceptsReturn=true,MinHeight=80,MaxHeight=180},_result=new(){IsReadOnly=true,AcceptsReturn=true,MinHeight=150,MaxHeight=260,TextWrapping=Avalonia.Media.TextWrapping.Wrap};
 private readonly WrapPanel _commands=new(){Orientation=Orientation.Horizontal},_actions=new(){Orientation=Orientation.Horizontal};
 private Button? _cancel;private TaskCompletionSource? _idle;private CancellationTokenSource? _operation;private McpConnection? _connection;private McpBrowserLogin? _login;private string? _resultJson,_resultRevision;private bool _closing;
 public McpConnectorsWindow(McpSettingsStore store,IMcpSecrets secrets,ProjectSession session,Action refresh){
  _store=store;_secrets=secrets;_session=session;_refresh=refresh;Title="MCP Connectors";Width=1040;Height=790;MinWidth=760;MinHeight=580;WindowStartupLocation=WindowStartupLocation.CenterOwner;
  var root=new DockPanel{Margin=new Thickness(18),LastChildFill=true};var header=new StackPanel{Spacing=8};header.Children.Add(new TextBlock{Text="Connect your project to MCP tools",FontSize=22});header.Children.Add(new TextBlock{Text="Configure a local executable or a remote HTTPS server. Nothing connects or sends project data automatically.",TextWrapping=Avalonia.Media.TextWrapping.Wrap});header.Children.Add(_commands);
  Button Add(string title,Func<Task> action,Panel parent){var button=new Button{Content=title,Margin=new Thickness(0,0,6,6)};button.Click+=async(_,_)=>await Perform(action);parent.Children.Add(button);return button;}
  Add("Add Server",()=>Edit(null),_commands);Add("Edit Server",()=>Edit(Selected()),_commands);Add("Remove Server",Remove,_commands);Add("Add Demo",AddDemo,_commands);Add("Connect",Connect,_commands);Add("Disconnect",Disconnect,_commands);Add("Refresh Tools",async()=>{await RequireConnection().RefreshToolsAsync(_operation!.Token);LoadTools();},_commands);
  var cancel=new Button{Content="Cancel Operation",IsVisible=false};_cancel=cancel;cancel.Click+=(_,_)=>_operation?.Cancel();header.Children.Add(cancel);header.Children.Add(_status);header.Children.Add(_progress);DockPanel.SetDock(header,Dock.Top);root.Children.Add(header);
  var close=new Button{Content="Close",HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,10,0,0)};close.Click+=(_,_)=>Close();DockPanel.SetDock(close,Dock.Bottom);root.Children.Add(close);
  var grid=new Grid{ColumnDefinitions=new("230,16,*"),Margin=new Thickness(0,12,0,0)};grid.Children.Add(_servers);var body=new StackPanel{Spacing=8};Grid.SetColumn(body,2);grid.Children.Add(new ScrollViewer{Content=body, [Grid.ColumnProperty]=2});
  body.Children.Add(new TextBlock{Text="Available tools",FontWeight=Avalonia.Media.FontWeight.SemiBold});body.Children.Add(_toolSearch);body.Children.Add(_tools);body.Children.Add(_description);body.Children.Add(new Expander{Header="Tool input schema",Content=_schema,HorizontalAlignment=HorizontalAlignment.Stretch});body.Children.Add(new TextBlock{Text="Arguments (JSON object)"});body.Children.Add(_arguments);body.Children.Add(_actions);Add("Review and Run",RunTool,_actions);Add("Import Selected Tasks",Import,_actions);body.Children.Add(new TextBlock{Text="Tool result (plain text)"});body.Children.Add(_result);root.Children.Add(grid);Content=root;
  _tools.SelectionChanged+=(_,_)=>{if(_tools.SelectedItem is McpToolInfo tool){_description.Text=tool.Description;_schema.Text=JsonSerializer.Serialize(tool.Schema,new JsonSerializerOptions{WriteIndented=true});_arguments.Text="{}";}};
  _toolSearch.TextChanged+=(_,_)=>LoadTools();
  Closing+=async(_,e)=>{if(_closing)return;e.Cancel=true;_operation?.Cancel();_closing=true;try{foreach(var owned in OwnedWindows.ToArray())owned.Close();if(_idle!=null)await _idle.Task;await Disconnect();}catch{ }Close();};LoadServers();UiIcons.ApplyTo(this);
 }
 private McpServerDefinition Selected()=>_servers.SelectedItem as McpServerDefinition??throw new InvalidOperationException("Choose a server first.");
 private McpConnection RequireConnection()=>_connection?.Connected==true?_connection:throw new InvalidOperationException("Connect to a server first.");
 private void LoadServers(string? id=null){_servers.ItemsSource=_store.Servers.ToArray();_servers.SelectedItem=_store.Servers.FirstOrDefault(s=>s.Id==id);}
 private void LoadTools(){_tools.ItemsSource=_connection?.Tools.Where(t=>(t.Name+" "+t.Description).Contains(_toolSearch.Text??"",StringComparison.OrdinalIgnoreCase)).ToArray();_tools.SelectedIndex=_connection?.Tools.Count>0?0:-1;}
 private async Task Perform(Func<Task> action){if(_operation!=null||_closing)return;using var cancellation=new CancellationTokenSource(TimeSpan.FromMinutes(3));_idle=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);_operation=cancellation;_progress.IsVisible=true;_cancel!.IsVisible=true;_commands.IsEnabled=_actions.IsEnabled=_servers.IsEnabled=false;try{await action();}catch(OperationCanceledException){_status.Text="Operation canceled. You can reconnect or try again.";}catch(Exception error){_status.Text="Could not complete connector action: "+error.Message;}finally{_operation=null;_progress.IsVisible=false;_cancel!.IsVisible=false;_idle?.TrySetResult();if(!_closing)_commands.IsEnabled=_actions.IsEnabled=_servers.IsEnabled=true;}}
 private async Task Connect(){var definition=Selected();await Disconnect();_status.Text="Connecting to "+definition.Name+"…";if(definition.Authentication==McpAuthentication.BrowserOAuth)_login=new();_connection=new(definition,_secrets,_login==null?null:_login.Authorize);try{await _connection.ConnectAsync(_operation!.Token,redirectUri:_login?.RedirectUri);LoadTools();_status.Text=$"Connected to {_connection.ServerName} · MCP {_connection.Protocol} · {_connection.Tools.Count} tools";}catch{await Disconnect();throw;}}
 private async Task Disconnect(){_gate.Clear();_resultJson=_resultRevision=null;_result.Text="";var connection=_connection;_connection=null;_tools.ItemsSource=null;_description.Text="Connect to a server to discover its tools.";_schema.Text="";try{if(connection!=null)await connection.DisposeAsync();}finally{_login?.Dispose();_login=null;}_status.Text="Disconnected.";}
 private async Task Edit(McpServerDefinition? existing){await Disconnect();var editor=new McpServerEditor(existing,_secrets);var value=await editor.ShowDialog<McpServerDefinition?>(this);if(value==null)return;if(existing!=null)_store.Servers.Remove(existing);_store.Servers.Add(value);_store.Save();LoadServers(value.Id);_status.Text="Server saved. Choose Connect to start it.";}
 private async Task Remove(){var selected=Selected();if(!await McpReviewWindow.Confirm(this,"Remove Server","Remove the saved setup and its credentials for "+selected.Name+"?","Remove"))return;await Disconnect();_store.Servers.Remove(selected);_store.Save();_secrets.Remove(selected.Id,"Bearer");foreach(var name in selected.SecretEnvironmentNames??[])_secrets.Remove(selected.Id,"Env_"+name);LoadServers();}
 public static McpServerDefinition DemoDefinition(){var (executable,args)=Program.SelfCommand("--mcp-demo-server");return new(Guid.NewGuid().ToString(),"Planora Demo",McpConnectorTransport.LocalStdio,executable,args);}
 private async Task AddDemo(){await Disconnect();var value=DemoDefinition();_store.Servers.Add(value);_store.Save();LoadServers(value.Id);_status.Text="Demo added. Connect, choose example_tasks, then Review and Run.";}
 private async Task RunTool(){var connection=RequireConnection();var tool=_tools.SelectedItem as McpToolInfo??throw new InvalidOperationException("Choose a tool.");var json=_arguments.Text??"{}";McpArgumentValidator.Validate(json,tool.Schema);string revision=_revision.Current(_session);var proposal=new McpToolProposal(connection.Definition.Id,tool.Name,json,connection.ReviewRevision(revision),false,true);proposal.Validate();string review=$"Server: {connection.Definition.Name}\nAddress: {connection.Definition.Address}\nArguments: {JsonSerializer.Serialize(connection.Definition.Arguments)}\nTool: {tool.Name}\n\nJSON sent to the server:\n{json}\n\nThis call may change the external service. Server descriptions and read-only hints do not grant permission. Only the JSON shown above is sent; your project is not attached. Local executables run with your Windows account.";
  if(!await McpReviewWindow.Confirm(this,"Review Tool Call",review,"Run Tool"))return;var approval=_gate.Approve(proposal);_status.Text="Running "+tool.Name+"…";_resultJson=null;_resultRevision=null;var result=await connection.InvokeAsync(proposal,approval,_gate,()=>_revision.Current(_session),_operation!.Token);_resultJson=result;_resultRevision=revision;_result.Text=result.Length>131072?result[..131072]+"\n[Display truncated; full result retained for task import.]":result;_status.Text="Tool returned. Review the result before importing any tasks.";
 }
 private async Task Import(){if(_resultJson==null||_resultRevision!=_revision.Current(_session))throw new InvalidOperationException("Run a tool again before importing: the result is missing or the project changed.");var rows=McpTaskImport.Parse(_resultJson);var selected=await new McpTaskImportWindow(rows,_session.Document?.Name).ShowDialog<IReadOnlyList<McpImportedTask>?>(this);if(selected==null)return;if(_resultRevision!=_revision.Current(_session))throw new InvalidOperationException("The project changed. Review a new tool result.");bool created=_session.Document==null;if(created)_session.NewProject("MCP Import",DateTime.Today.AddHours(8));try{McpTaskImport.Apply(_session,selected);}catch{if(created)_session.CloseProject();throw;}_refresh();_resultRevision=null;_status.Text=$"Imported {selected.Count} tasks. Close this panel to edit them or Undo the import.";}
}

public sealed class McpReviewWindow : Window {
 public McpReviewWindow(string title,string text,string accept){Title=title;Width=710;Height=530;WindowStartupLocation=WindowStartupLocation.CenterOwner;var root=new DockPanel{Margin=new Thickness(18)};var actions=new StackPanel{Orientation=Orientation.Horizontal,Spacing=10,HorizontalAlignment=HorizontalAlignment.Right};var cancel=new Button{Content="Cancel"};cancel.Click+=(_,_)=>Close(false);var run=new Button{Content=accept};run.Classes.Add("primary");run.Click+=(_,_)=>Close(true);actions.Children.Add(cancel);actions.Children.Add(run);DockPanel.SetDock(actions,Dock.Bottom);root.Children.Add(actions);root.Children.Add(new TextBox{Text=text,IsReadOnly=true,AcceptsReturn=true,TextWrapping=Avalonia.Media.TextWrapping.Wrap,Margin=new Thickness(0,0,0,12)});Content=root;UiIcons.ApplyTo(this);}
 public static Task<bool> Confirm(Window owner,string title,string text,string accept)=>new McpReviewWindow(title,text,accept).ShowDialog<bool>(owner);
}
public sealed class McpTaskImportWindow : Window {
 public McpTaskImportWindow(IReadOnlyList<McpImportedTask> rows,string? projectName){Title="Review Task Import";Width=760;Height=570;WindowStartupLocation=WindowStartupLocation.CenterOwner;var root=new DockPanel{Margin=new Thickness(18)};var label=new TextBlock{Text=projectName==null?"Create a new project and add the selected tasks.":"Append selected tasks to "+projectName+". One Undo removes the import.",TextWrapping=Avalonia.Media.TextWrapping.Wrap};DockPanel.SetDock(label,Dock.Top);root.Children.Add(label);var footer=new StackPanel{Spacing=8};footer.Children.Add(new TextBlock{Text="Imports Name, Duration, Start, Finish, Completion and Notes as automatic tasks. Other fields are ignored.",TextWrapping=Avalonia.Media.TextWrapping.Wrap});var actions=new StackPanel{Orientation=Orientation.Horizontal,Spacing=10};var cancel=new Button{Content="Cancel"};var apply=new Button{Content="Import Tasks"};apply.Classes.Add("primary");actions.Children.Add(cancel);actions.Children.Add(apply);footer.Children.Add(actions);DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);var list=new StackPanel{Spacing=5,Margin=new Thickness(0,12)};var checks=rows.Select(r=>new CheckBox{Content=$"{r.Name} · {r.Duration} · {r.Start} – {r.Finish} · {r.Progress}%",IsChecked=true,Tag=r}).ToArray();foreach(var check in checks){ToolTip.SetTip(check,((McpImportedTask)check.Tag!).Notes);list.Children.Add(check);}root.Children.Add(new ScrollViewer{Content=list});cancel.Click+=(_,_)=>Close(null);apply.Click+=(_,_)=>{var selected=checks.Where(c=>c.IsChecked==true).Select(c=>(McpImportedTask)c.Tag!).ToArray();if(selected.Length>0)Close((IReadOnlyList<McpImportedTask>)selected);};Content=root;UiIcons.ApplyTo(this);}
}
